mapper.select:
SELECT id, ds_id, task_type, target_object_type, target_object, suggested_change,
       evidence, status, reviewer, review_comment, reviewed_at, create_time, update_time
FROM kb_review_task
WHERE ds_id = #{dsId}

    AND status = #{status}


    AND task_type = #{taskType}


    AND target_object_type = #{targetObjectType}


    AND reviewer = #{reviewer}


    AND create_time >= #{startTime}


    AND create_time <= #{endTime}

ORDER BY create_time DESC
